mapper.select:
SELECT d.id, d.declaration_no as declarationNo, d.status, d.total_amount as totalAmount, d.currency, d.created_at as createdAt, -- 联查供应商表 s.supplier_code AS supplierCode, s.supplier_name AS supplierName, s.contact_person AS contactPerson, -- 联查保税仓库表 w.warehouse_code AS warehouseCode, w.warehouse_name AS warehouseName, w.location FROM biz_customs_declaration d LEFT JOIN sys_supplier s ON d.supplier_id = s.id LEFT JOIN sys_warehouse w ON d.warehouse_id = w.id
AND d.declaration_no = #{declarationNo}
AND d.status = #{status}
ORDER BY d.created_at DESC
